using DemaConsulting.WordSense;

namespace WordSense.Builder;

/// <summary>
///     Builds the word table of the core package (<c>words.bin</c>) from the corpus.
/// </summary>
/// <remarks>
///     The table answers every known word with its senses. A lemma that has trained weights answers with all of its
///     senses (in the ordinal order of the sense labels, the order of the trained classes) and so do its forms listed in
///     <c>corpus/forms</c>; a dictionary word answers with one sense per part of speech and no meaning; an inflected form
///     generated by <see cref="MorphologyExpander"/> answers with one sense of its base. A lemma's own senses win over
///     every other source, then forms, then dictionary words, then generated forms.
/// </remarks>
internal static class WordsBuilder
{
    /// <summary>
    ///     The location of the table in the core package, relative to the repository root.
    /// </summary>
    public const string DefaultOutput = "src/DemaConsulting.WordSense/Resources/words.bin";

    /// <summary>
    ///     Builds the table.
    /// </summary>
    /// <param name="corpus">The corpus directory.</param>
    /// <returns>The entries by word, in ordinal order.</returns>
    /// <exception cref="InvalidDataException">Thrown when the corpus is inconsistent.</exception>
    public static SortedDictionary<string, WordDetails[]> Build(string corpus)
    {
        var inventory = SenseInventory.ReadDirectory(Path.Combine(corpus, "senses"));
        var errors = inventory.ValidateRules();
        if (errors.Count > 0)
        {
            throw new InvalidDataException(string.Join(Environment.NewLine, errors));
        }

        var entries = new SortedDictionary<string, WordDetails[]>(StringComparer.Ordinal);
        var senses = new Dictionary<string, WordDetails[]>(StringComparer.Ordinal);
        foreach (var lemma in inventory.Rows.Select(r => r.Lemma).Distinct(StringComparer.Ordinal))
        {
            var details = new LemmaEntry(lemma, inventory.DefinitionsOf(lemma), true).Candidates.ToArray();
            senses[lemma] = details;
            entries[lemma] = details;
        }

        // The forms of a lemma answer with the lemma's senses
        var formsDirectory = Path.Combine(corpus, "forms");
        if (Directory.Exists(formsDirectory))
        {
            foreach (var (form, lemma, _) in Directory.GetFiles(formsDirectory, "*.tsv").OrderBy(f => f, StringComparer.Ordinal).SelectMany(Corpus.ReadForms))
            {
                if (senses.TryGetValue(lemma, out var details))
                {
                    entries.TryAdd(form, details);
                }
            }
        }

        // Dictionary words: one sense per part of speech
        var lexiconPath = Path.Combine(corpus, "lexicon", "lexicon.tsv");
        var lexicon = File.Exists(lexiconPath) ? LexiconSource.ReadWords(lexiconPath) : [];
        var singles = new Dictionary<(string, PartOfSpeech), WordDetails[]>();
        WordDetails[] Single(string lemma, PartOfSpeech pos)
        {
            if (!singles.TryGetValue((lemma, pos), out var one))
            {
                singles[(lemma, pos)] = one = [new WordDetails(lemma, pos, null, null)];
            }

            return one;
        }

        var dictionaryBases = new List<(string Word, byte Mask)>();
        foreach (var (word, mask) in lexicon)
        {
            if (entries.ContainsKey(word))
            {
                continue;
            }

            var details = new List<WordDetails>();
            for (var bit = 0; bit < LexiconSource.Letters.Length; bit++)
            {
                if ((mask & (1 << bit)) != 0)
                {
                    details.Add(Single(word, (PartOfSpeech)bit)[0]);
                }
            }

            entries[word] = details.ToArray();
            dictionaryBases.Add((word, mask));
        }

        // Generated forms of the dictionary words
        var enabled = MorphologyExpander.ReadEnabled(Path.Combine(corpus, "lexicon", "morphology.tsv"));
        foreach (var (form, details) in MorphologyExpander.Expand(dictionaryBases, entries.ContainsKey, enabled, Single))
        {
            entries.TryAdd(form, details);
        }

        return entries;
    }

    /// <summary>
    ///     Builds the table and writes it to a file.
    /// </summary>
    /// <param name="corpus">The corpus directory.</param>
    /// <param name="output">The file to write.</param>
    /// <returns>The number of words in the table.</returns>
    public static int Write(string corpus, string output)
    {
        var entries = Build(corpus);
        var directory = Path.GetDirectoryName(Path.GetFullPath(output));
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        File.WriteAllBytes(output, WordsBlobWriter.Write(entries));
        return entries.Count;
    }
}
